WITH parsed AS (SELECT id, plan, currency, tier_prices, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT plan, SUM(CASE WHEN plan = 'starter' THEN avg_tier_price ELSE 0 END) AS starter_avg_tier_price, SUM(avg_tier_price) FILTER (WHERE currency = 'EUR') AS eur_total_avg_tier_price, SUM(CASE WHEN currency = 'THB' THEN avg_tier_price ELSE 0 END) AS thb_avg_tier_price FROM parsed GROUP BY plan ORDER BY starter_avg_tier_price ASC NULLS LAST
